from pathlib import Path
import csv,json,hashlib,collections,math
ROOT=Path('/home/russell/wt/crypto-executable-cells-20261018')
D=ROOT/'children/crypto_trading/docs/memos'
P='2026-10-18-executable-cells'
inputs={}
def read(name):
 p=D/name;inputs[name]=hashlib.sha256(p.read_bytes()).hexdigest()
 with p.open() as f:return list(csv.DictReader(f))
def ids(s):return set(s.split(';')) if s else set()
def number(s):
 try:return float(s)
 except:return float('nan')
def binstr(n):n=10*int(float(n));return f'{n:02d}-{n+10:02d}'
def key(v,a,l,b,s):return (v,a,int(float(l)),b,{'Up':'YES','Down':'NO'}.get(s,s))
ledger=read(P+'-coverage-ledger.csv')
records={}
for r in ledger:
 k=key(r['venue'],r['asset'],r['lead_minutes'],r['up_probability_bin'],r['side'])
 records[k]={'base':r,'reasons':set(),'prior_selected':set(),'prior_raw':set(),'prior_cal':set(),'new_raw':set(),'new_cal':set(),'positive':collections.defaultdict(list),'gap':'','prediction_only':True}
assert len(records)==600
for r in read('2026-10-18-candidate-inventory-cells.csv'):
 for side in ['YES','NO']:
  z=records[key('Kalshi',r['asset'],r['lead'],r['bin'],side)]
  for field,source,reason in [('prior_selected','preselected_ids','prior_warmup_selected'),('prior_raw','support_ids','two_period_raw_score_support'),('prior_cal','calibration_support_ids','two_period_calibrated_score_support')]:
   z[field]=ids(r[source]);z['reasons'].update([reason] if z[field] else [])
  if r['material_gap']=='True':z['reasons'].add('prior_persistent_material_mean_gap');z['gap']=r['gap_direction']+'; descriptive cell mean, not a side-specific model signal'
for r in read('2026-10-18-polymarket-predictability-inventory.csv'):
 for side in ['Up','Down']:
  z=records[key('Polymarket','BTC',r['lead_minutes'],r['probability_bin'],side)]
  for field,source,reason in [('prior_selected','warmup_selected_methods','prior_warmup_selected'),('prior_raw','two_period_raw_support_methods','two_period_raw_score_support'),('prior_cal','two_period_calibration_support_methods','two_period_calibrated_score_support')]:
   z[field]={'model'+str(int(x)).zfill(2) for x in ids(r[source])};z['reasons'].update([reason] if z[field] else [])
  if number(r['warmup_gap'])*number(r['validation_gap'])>0:
   z['reasons'].add('persistent_same_direction_mean_gap');z['gap']='UP' if number(r['warmup_gap'])>0 else 'DOWN'
   z['gap']+=' underpriced in both period means; descriptive, not a side-specific model signal'
for r in read(P+'-poly-prediction-cells.csv'):
 for side in ['Up','Down']:
  z=records[key('Polymarket','BTC',r['lead'],binstr(r['bin']),side)]
  for field,metric,reason in [('new_raw','market_ll_gain_mean','native_transfer_raw_score_gain'),('new_cal','cal_ll_gain_mean','native_transfer_calibrated_score_gain')]:
   if number(r[metric])>0:z[field].add('model'+str(int(r['method'])).zfill(2));z['reasons'].add(reason)
for name,venue in [(P+'-kalshi-cost-scenarios.csv','Kalshi'),(P+'-poly-execution-scenarios.csv','Polymarket')]:
 for r in read(name):
  if not (number(r['n'])>0 and math.isfinite(number(r['mean'])) and number(r['mean'])>0):continue
  k=key(venue,r.get('asset','BTC'),r['lead'],binstr(r['bin']),r['side'])
  z=records[k];policy=r.get('model',r.get('policy'))
  # Exact output row coordinates, not winners or sample-size-filtered best settings.
  if venue=='Kalshi':coord=f"{r['stage']}/size={r['shares']}"
  else:coord=f"lag={r['latency_s']}/age_ms={r['age_cap_ms']}/size={r['shares']}"
  z['positive'][policy].append({'row':coord,'n':int(float(r['n'])),'mean':number(r['mean']),'adequate':r['adequate'],'tail_warning':r['tail_warning']})
  diagnostic=policy=='unconditional'
  z['reasons'].add('positive_unconditional_diagnostic_only' if diagnostic else 'positive_side_matched_cost_scenario')
  if not diagnostic:z['prediction_only']=False
rows=[]
for k,z in records.items():
 v,a,l,b,s=k;r=z['base'];blocked=a!='BTC' and v=='Polymarket'
 if blocked:role='blocked_native_inventory';z['reasons'].add('native_pending_book_inventory_no_settled_training_panel')
 elif z['reasons']:role='candidate_hypothesis'
 else:role='full_grid_no_current_support'
 positive=z['positive']; matched=[x for p,xx in positive.items() if p!='unconditional' for x in xx]
 fields={f:';'.join(sorted(z[f])) for f in ['prior_selected','prior_raw','prior_cal','new_raw','new_cal']}
 if v=='Kalshi':
  done='All77 saved model settings plus raw/logistic controls; both warmup/validation; both sides;1/10/100share cent-fee quote scenarios; matched original prediction losses; day/week uncertainty; multiplicity;0.5/1cent cost stress; sample/zero-loss flags. Historical candle scenarios are not delayed fills.'
  nexttest='For EVERY listed model/cell, retain chronology and raw/cal controls; obtain same-window native exchange/availability-stamped depth and effective fees, or separately admitted causal feature/model history. Apply both-source freshness gates,1/5second delay,1/10/100share depth,2/10/60second age,fee/slippage sensitivity,day/week and halves,rare-loss audit. No replay possible from current minute-rounded October books.'
  limitation=r['blocker']+' All dates reused; positive means are exploratory; cell-level score support is not side-specific profitability.'
  disposition='candidate_execution_test_data_blocked' if role=='candidate_hypothesis' else 'retain_grid_existing_tests_complete_no_new_support'
 elif not blocked:
  done='All20 fixed native models plus raw/cal controls and separate unconditional diagnostic;1/5second latency x2/10/60second age x1/10/100share depth; exact native outcomes; matched score/freshness comparisons; fee and0.5/1cent cost stress;day/week/multiplicity;fixed halves;zero-loss and added-loss stress. No omitted candidate-specific aggregation remains.'
  nexttest='For EVERY listed model/cell, first audit admissible uninspected native history and correct COR-1 with regression; freeze same-model/control replication before labels. Repeat source+purchased-token freshness,fee vintage/per-match rounding,positive latency/depth,rare-loss,day/week/halves and overlap audit. If no admissible period exists, mark replication blocked; do not replace a failed cell or tune thresholds.'
  limitation='Retrospective selection; displayed depth is not observed fills;fee-vintage/label-publication gaps. COR-1: only one unconditional Down8m row at3sizes affected, zero selected model/raw/cal rows. Sparse/all-win/alternate-only gains remain uncertain; no corrected profit confirmation.'
  disposition='candidate_existing_sensitivity_tests_complete_independent_replication_unestablished' if role=='candidate_hypothesis' else 'retain_grid_existing_tests_complete_no_new_support'
 else:
  done='Raw native book inventory:92pending markets,approximately22.5hours perasset;no retained terminal outcomes. No BTC/Kalshi model or label substituted.'
  nexttest='Acquire native settled labels/rules,publication times and earlier causal native training history; verify exact token strings and book/fee vintages. Then freeze native baseline/model comparisons and run all declared freshness,latency,depth,cost,rare-loss/stability tests for this exact cell/side; do not infer a profitable hypothesis from inventory.'
  limitation=r['blocker']+' No fitted native model or score/cost evidence.';disposition='native_training_and_settlement_data_blocked'
 if role=='full_grid_no_current_support':nexttest='Retain this exact cell/side in future eligible full-grid controls; existing tests show no union-screen support. This is not proof of impossibility. No further tuning on reused outcomes.'
 rows.append({'venue':v,'asset':a,'lead_minutes':l,'up_probability_bin':b,'side':('UP' if s=='YES' else 'DOWN') if v=='Polymarket' else s,'role':role,'selection_reasons':';'.join(sorted(z['reasons'])),**fields,'mean_gap_evidence':z['gap'],'side_matched_positive_policies':';'.join(sorted(p for p in positive if p!='unconditional')),'unconditional_diagnostic_positive':bool(positive.get('unconditional')),'positive_scenario_coordinates_json':json.dumps(positive,separators=(',',':'),sort_keys=True),'positive_side_scenarios':len(matched),'positive_sparse_side_scenarios':sum(x['adequate']!='True' for x in matched),'positive_tail_warning_side_scenarios':sum(x['tail_warning']=='True' for x in matched),'evidence_scope':'side-matched cost scenario plus separate cell-score evidence' if matched else ('cell probability score/mean-gap only; does not identify a profitable side' if role=='candidate_hypothesis' else 'inventory only' if blocked else 'no union-screen support'),'side_evidence_assignment':'matched purchased side for cost evidence; cell-score evidence remains side-unassigned' if matched else 'side-unassigned; both sides require testing' if role=='candidate_hypothesis' else 'inventory only','completed_tests':done,'limitations':limitation,'disposition':disposition,'next_decisive_test':nexttest,'minimum_data':r['minimum_data'],'established_profit':False,'sources':'2026-10-18-candidate-inventory-cells.csv' if v=='Kalshi' else '2026-10-18-polymarket-predictability-inventory.csv;'+P+'-poly-prediction-cells.csv' if not blocked else P+'-coverage-ledger.csv','side_cost_source':P+('-kalshi-cost-scenarios.csv' if v=='Kalshi' else '-poly-execution-scenarios.csv') if not blocked else ''})
p=D/(P+'-candidate-followup.csv')
with p.open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
counts=collections.Counter(r['role'] for r in rows)
groups=[]
for venue,asset in sorted({(r['venue'],r['asset']) for r in rows}):
 subset=[r for r in rows if (r['venue'],r['asset'])==(venue,asset)]
 groups.append({'venue':venue,'asset':asset,'roles':dict(collections.Counter(r['role'] for r in subset)),'candidate_groups':{str(lead):{side:sorted(r['up_probability_bin'] for r in subset if r['lead_minutes']==lead and r['side']==side and r['role']=='candidate_hypothesis') for side in sorted({r['side'] for r in subset})} for lead in [2,5,8,11,14]}})
summary={'counts':dict(counts),'groups':groups,'candidate_with_side_cost':sum(r['role']=='candidate_hypothesis' and r['positive_side_scenarios']>0 for r in rows),'candidate_probability_or_gap_only':sum(r['role']=='candidate_hypothesis' and r['positive_side_scenarios']==0 for r in rows),'candidate_with_prior_selection':sum(bool(r['prior_selected']) for r in rows),'positive_scenario_coordinates':sum(len(v) for z in records.values() for v in z['positive'].values()),'inputs':inputs,'output':{'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()},'rule':'Inclusive union of prior warmup selection, two-period raw/calibration score support, prior material Kalshi or persistent-sign Poly mean gaps, native transfer raw/calibrated score gains, and any strictly positive saved side/policy scenario with n>0 at any declared size/age/lag/period. No adequacy/top-k/model cutoff. Unconditional diagnostics separately marked; probability-only evidence duplicated across side inventory is not side-specific evidence. Blocked native assets remain inventory, not positive hypotheses. All600grid entries retained.','numerical_outputs_changed':False}
Path('/home/russell/data/crypto_trading/research/executable-cells-20261018/candidate-followup-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
