import csv,json,math,hashlib,subprocess
from pathlib import Path
D=Path('/home/russell/wt/crypto-executable-cells-20261018/children/crypto_trading/docs/memos')
P='2026-10-18-executable-cells'
def read(n):return list(csv.DictReader((D/n).open()))
R=read(P+'-candidate-followup.csv')
def k(r):return r['venue'],r['asset'],int(r['lead_minutes']),r['up_probability_bin'],r['side']
M={k(r):r for r in R}
def test_complete_unique_dispositions():
 assert len(M)==len(R)==600
 assert sum(r['role']=='candidate_hypothesis' for r in R)==298
 assert sum(r['role']=='blocked_native_inventory' for r in R)==300
 assert sum(r['role']=='full_grid_no_current_support' for r in R)==2
 assert len({k(r)[:4] for r in R if r['role']=='candidate_hypothesis'})==150
 assert all(r['next_decisive_test'] and r['limitations'] and r['completed_tests'] for r in R)
 assert all(r['established_profit']=='False' for r in R)
def test_every_positive_scenario_preserved_exactly():
 expected=set()
 for venue,suffix in [('Kalshi','kalshi-cost-scenarios'),('Polymarket','poly-execution-scenarios')]:
  for x in read(P+'-'+suffix+'.csv'):
   n=float(x['n']);mean=float(x['mean']) if x['mean'] else math.nan
   if not(n>0 and math.isfinite(mean) and mean>0):continue
   low=10*int(x['bin']);side={'Up':'UP','Down':'DOWN'}.get(x['side'],x['side'])
   key=(venue,x.get('asset','BTC'),int(x['lead']),f'{low:02d}-{low+10:02d}',side)
   policy=x.get('model',x.get('policy'))
   coord=f"{x['stage']}/size={x['shares']}" if venue=='Kalshi' else f"lag={x['latency_s']}/age_ms={x['age_cap_ms']}/size={x['shares']}"
   expected.add((key,policy,coord,int(n),mean,x['adequate'],x['tail_warning']))
 actual={(k(r),policy,x['row'],x['n'],x['mean'],x['adequate'],x['tail_warning']) for r in R for policy,rows in json.loads(r['positive_scenario_coordinates_json']).items() for x in rows}
 assert actual==expected
 assert len(actual)==27866
 assert any(x[3]<200 for x in actual)
 assert any(x[5]=='False' for x in actual)
def test_side_scope_and_nonbtc_not_positive_claims():
 no_cost=[r for r in R if r['role']=='candidate_hypothesis' and int(r['positive_side_scenarios'])==0]
 assert len(no_cost)==75
 assert all(r['side_evidence_assignment']=='side-unassigned; both sides require testing' for r in no_cost)
 for r in R:
  if r['role']=='blocked_native_inventory':
   assert not r['side_matched_positive_policies'] and not r['prior_selected'] and not r['prior_raw'] and not r['prior_cal']
  assert 'unconditional' not in r['side_matched_positive_policies'].split(';')
def test_prior_support_never_dropped():
 for x in read('2026-10-18-candidate-inventory-cells.csv'):
  for side in ['YES','NO']:
   r=M['Kalshi',x['asset'],int(x['lead']),x['bin'],side]
   for target,source in [('prior_selected','preselected_ids'),('prior_raw','support_ids'),('prior_cal','calibration_support_ids')]:
    assert set(filter(None,r[target].split(';')))==set(filter(None,x[source].split(';')))
   if x['material_gap']=='True':assert 'prior_persistent_material_mean_gap' in r['selection_reasons']
 for x in read('2026-10-18-polymarket-predictability-inventory.csv'):
  for side in ['UP','DOWN']:
   r=M['Polymarket','BTC',int(x['lead_minutes']),x['probability_bin'],side]
   for target,source in [('prior_selected','warmup_selected_methods'),('prior_raw','two_period_raw_support_methods'),('prior_cal','two_period_calibration_support_methods')]:
    assert set(filter(None,r[target].split(';')))=={'model'+str(int(i)).zfill(2) for i in x[source].split(';') if i}
def test_original_numeric_outputs_unchanged():
 root=D.parents[3]
 for p in D.glob(P+'-*.csv'):
  if p.name.endswith('-candidate-followup.csv'):continue
  prior=subprocess.check_output(['git','show','c2e064f06c0f54d1546847defee8136e4302bc0a:'+str(p.relative_to(root))],cwd=root)
  assert hashlib.sha256(prior).digest()==hashlib.sha256(p.read_bytes()).digest()
